import{_ as s,c as t,o as e,a2 as i}from"./chunks/framework.CIiVzG-O.js";const g=JSON.parse('{"title":"macOS 权限","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/permissions.md","filePath":"zh-CN/guide/permissions.md","lastUpdated":1793163976000}'),r={name:"zh-CN/guide/permissions.md"};function n(o,a,p,l,h,d){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="macos-权限" tabindex="-1">macOS 权限 <a class="header-anchor" href="#macos-权限" aria-label="Permalink to &quot;macOS 权限&quot;">​</a></h1><p>为了提供最佳体验，NueZip 可能会请求几项 macOS 权限。本页面说明每项权限的用途以及如何管理它们。</p><h2 id="文件与文件夹" tabindex="-1">文件与文件夹 <a class="header-anchor" href="#文件与文件夹" aria-label="Permalink to &quot;文件与文件夹&quot;">​</a></h2><p>为了访问系统中任意位置的归档，NueZip 需要文件访问权限。</p><p><strong>用途</strong>：读取归档文件、解压内容以及创建新归档。</p><p><strong>管理</strong>：系统设置 → <strong>隐私与安全性</strong> → <strong>文件与文件夹</strong></p><p>在首次启动弹出提示时授予访问权限。你可以随时管理或撤销访问权限。</p><h2 id="finder-扩展" tabindex="-1">Finder 扩展 <a class="header-anchor" href="#finder-扩展" aria-label="Permalink to &quot;Finder 扩展&quot;">​</a></h2><p>NueZip 包含一个 Finder 扩展，用于添加右键上下文菜单选项。</p><p><strong>用途</strong>：在 Finder 中右键点击归档文件，即可直接解压、压缩或使用 NueZip 打开。</p><p><strong>启用</strong>：系统设置 → <strong>隐私与安全性</strong> → <strong>扩展</strong> → <strong>Finder 扩展</strong> → 启用 <strong>NueZip</strong></p><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><p>NueZip 可能会针对长时间运行的操作（批量解压、大型归档压缩）显示通知。</p><p><strong>用途</strong>：在后台操作完成时提醒你。</p><p><strong>管理</strong>：系统设置 → <strong>通知</strong> → <strong>NueZip</strong></p><h2 id="完全磁盘访问-可选" tabindex="-1">完全磁盘访问（可选） <a class="header-anchor" href="#完全磁盘访问-可选" aria-label="Permalink to &quot;完全磁盘访问（可选）&quot;">​</a></h2><p>为了将归档解压到系统保护的位置，NueZip 可能会请求完全磁盘访问权限。</p><p><strong>用途</strong>：将解压出的文件写入用户文件夹之外的位置。</p><p><strong>管理</strong>：系统设置 → <strong>隐私与安全性</strong> → <strong>完全磁盘访问</strong></p><p>此权限为可选，仅在你处理系统级位置时才需要。</p><h2 id="使用终端重置权限" tabindex="-1">使用终端重置权限 <a class="header-anchor" href="#使用终端重置权限" aria-label="Permalink to &quot;使用终端重置权限&quot;">​</a></h2><p>如果权限对话框被关闭或状态不一致，你可以使用 <code>tccutil</code> 重置 macOS 的权限提示：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 重置 NueZip 的权限</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.nuezip</span></span></code></pre></div><p>运行 <code>tccutil</code> 后，重启应用并再次触发该功能以重新弹出提示。</p><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><ul><li>如果通知不显示，请检查 <strong>通知</strong> 权限是否已授予。</li><li>修改权限后，务必退出并重新打开 NueZip，更改才能生效。</li></ul><p>如需更多帮助，请访问 <a href="./troubleshooting.html">故障排除指南</a>。</p>`,27)])])}const u=s(r,[["render",n]]);export{g as __pageData,u as default};
